{% code matlab example lang:matlab %} % 多图合一，图1 x = linspace(0,30); t = tiledlayout(1,2); t.Padding = &lsquo;compact&rsquo;; t.TileSpacing = &lsquo;compact&rsquo;; subcol = &lsquo;#228b22&rsquo;;%深绿色 % 插入左图 nexttile %当4a+c^2=0时的情况 % 设置线宽和颜色 lsize=1.5; lcolor=&rsquo;m&rsquo;; Fsize=26; gcasize=26; % 设置fp t=0:0.01:6.29; fp=cos(t)+1i.sin(t); c_1=1/64.(16+4fp-fp.^2+sqrt((16+4fp-fp.^2).^2-16.(fp.^2+2fp+4).(4-fp.^2))); c_2=1/64.(16+4fp-fp.^2-sqrt((16+4fp-fp.^2).^2-16.(fp.^2+2fp+4).(4-fp.^2))); a_1=-c_1.^2/4; a_2=-c_2.^2/4; plot(a_1,&lsquo;Color&rsquo;,&lsquo;r&rsquo;,&rsquo;linewidth&rsquo;,lsize); hold on plot(a_2,&lsquo;Color&rsquo;,&lsquo;b&rsquo;,&rsquo;linewidth&rsquo;,lsize); plot(a_1,&lsquo;Color&rsquo;,&lsquo;r&rsquo;,&rsquo;linewidth&rsquo;,lsize); hold on plot(a_2,&lsquo;Color&rsquo;,&lsquo;b&rsquo;,&rsquo;linewidth&rsquo;,lsize); handle=legend( &hellip; &lsquo;$a_+$&rsquo;, &hellip; &lsquo;$a_-$&rsquo; &hellip; ); set(handle,&lsquo;Box&rsquo;,&lsquo;off&rsquo;, &lsquo;interpreter&rsquo;,&rsquo;latex&rsquo;,&lsquo;FontSize&rsquo;,Fsize); xtickformat(&rsquo;%.2f&rsquo;); %设置小数精度 ytickformat(&rsquo;%.3f&rsquo;); pos=axis;%取得当前坐标轴的范围[xmin xmax ymin ymax] text(pos(1)+0.003,pos(4)-0.002,&lsquo;a&rsquo;,&lsquo;FontSize&rsquo;,30,&lsquo;color&rsquo;,subcol); xlabel(&lsquo;Re(a)&rsquo;,&lsquo;FontSize&rsquo;,Fsize); ylabel(&lsquo;Im(a)&rsquo;,&lsquo;FontSize&rsquo;,Fsize); set(gca,&lsquo;LooseInset&rsquo;,max(get(gca,&lsquo;TightInset&rsquo;),1)); set(gca,&lsquo;Box&rsquo;,&lsquo;off&rsquo;,&lsquo;FontSize&rsquo;,gcasize,&lsquo;Fontname&rsquo;,&lsquo;Times New Roman&rsquo;); % 插入右图 nexttile % 设置线宽和颜色 lsize=1.5; lcolor=&rsquo;m&rsquo;; Fsize=26; gcasize=26; % 设置fp t=0:0.0001:6.29; fp=cos(t)+1i.sin(t); c_1=1/64.(16+4fp-fp.^2+sqrt((16+4fp-fp.^2).^2-16.(fp.^2+2fp+4).(4-fp.^2))); c_2=1/64.(16+4fp-fp.^2-sqrt((16+4fp-fp.^2).^2-16.(fp.^2+2fp+4).(4-fp.^2))); a_1=-c_1.^2/4; a_2=-c_2.^2/4; plot(c_1,&lsquo;Color&rsquo;,&lsquo;r&rsquo;,&rsquo;linewidth&rsquo;,lsize); hold on plot(c_2,&lsquo;Color&rsquo;,&lsquo;b&rsquo;,&rsquo;linewidth&rsquo;,lsize); handle=legend( &hellip; &lsquo;$c_+$&rsquo;, &hellip; &lsquo;$c_-$&rsquo; &hellip; ); set(handle,&lsquo;Box&rsquo;,&lsquo;off&rsquo;, &lsquo;interpreter&rsquo;,&rsquo;latex&rsquo;,&lsquo;FontSize&rsquo;,Fsize); xtickformat(&rsquo;%.2f&rsquo;); %设置小数精度 ytickformat(&rsquo;%.3f&rsquo;); pos=axis;%取得当前坐标轴的范围[xmin xmax ymin ymax] text(pos(1)+0.02,pos(4)-0.015,&lsquo;b&rsquo;,&lsquo;FontSize&rsquo;,30,&lsquo;color&rsquo;,subcol); xlabel(&lsquo;Re(c)&rsquo;,&lsquo;FontSize&rsquo;,Fsize); ylabel(&lsquo;Im(c)&rsquo;,&lsquo;FontSize&rsquo;,Fsize); set(gca,&lsquo;Box&rsquo;,&lsquo;off&rsquo;,&lsquo;FontSize&rsquo;,gcasize,&lsquo;Fontname&rsquo;,&lsquo;Times New Roman&rsquo;); {% endcode %}

   {% label success@2023年04月25日星期二晴北京市北京师范大学 %} 今天开始补充一些vim的高级技巧，以增加工作能力。对于尚没有学会使用vim的同学，可以参考我的另一篇文章 vim-nvim使用手册 或者也可以直接在终端使用命令vimtutor打开手册学习（建议使用这个方法）
常用命令 {% label success@2023年04月28日星期五阴北京市北京师范大学 %}
命令 功能 dip 在空白行使用，删除所有临近空白行 :g/^\s*$/d 删除文档中的所有空行 viw 在空白区使用，选择所有空白 :nohl 清除vim高亮 :x 与zz和:wq类似，但不会写入没有修改过的文件 % 插入模式，将当前文件名输入到文件中 ~ 转换大小写 &#39;&#39; 跳回上次位置 `&#39; 跳回上次位置 :r 在当前位置插入文件file Esc 退出插入模式 CTRL+[ 退出插入模式 使用标签 命令 功能 :tabnew 打开新标签 :tabclose 关闭当前标签页 gt 切换到下一个标签 :tabp 切换到上一个标签 gT 切换到上一个标签 :tab ball 在单个选项卡中打开所有缓冲区 :tabs 列出所有可用的标签 CTRL-g 显示当前文件名 {% note success %} 切换标签命令gt可以理解为go tab ,那反过来逆向移动正好有大写字母对应，即gT。这和查找命令f正向查找，F逆向查找的道理是一样的。 {% endnote %}
使用宏命令 命令 功能 q 开始录制/停止录制 qa 录制宏保存在寄存器a中 :reg a 查看宏a命令内容 @a 执行宏a 4@a 执行4次宏a {% note success %} 由于宏是命令，所以录制宏的开始，结束，执行均是指在命令模式下按下按键。特别注意不是使用:command这种命令方式执行。宏命令可以将反复执行的操作录制下来，最大程度上提高了工作效率。 {% endnote %}
