  2023年04月22日星期六阴北京市北京师范大学,今天完成了第十次作业，同样还是在vim上完成，然后贴到Jupyter上，插入图片展示作业。同时今天获得vim整块代码移到的技巧，比如选中前十行，然后按shift+&gt;右移，同时shift+&lt;左移。第二个方法是命令模式，使用:m,n&gt;将第m行到第n行，右移shiftwidth，同时:m,n&lt;将第m行到第n行，左移shiftwidth,其中shiftwidth=4可以在/etc/vimrc中设置参数。
{% code Python爬取bnu网站数据 lang:python %} #! /usr/bin/env python3
-- coding: utf-8 -- vim:fenc=utf-8 Author: 冯振华 Version: 1.0 Date: 2023年 04月 22日 星期六 13:22:34 CST Copyright © 2023 feng feng@arch Distributed under terms of the MIT license. 导入库 import os import requests from bs4 import BeautifulSoup from requests.compat import urljoin
设置存储文件夹 dirname = &lsquo;./头条关注&rsquo; if not os.path.exists(dirname): #如果文件夹不存在，则创建 os.mkdir(dirname)
伪装成浏览器 header = {&lsquo;User-Agent&rsquo;: &lsquo;Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/86.0.4240.198 Safari/537.36&rsquo;} url = &lsquo; http://news.bnu.edu.cn/zx/ttgz/index.htm' html = requests.get(url, headers=header) html.encoding=&lsquo;utf-8&rsquo;
把url内容给bs去解析 bsObj = BeautifulSoup(html.content, &rsquo;lxml&rsquo;) lis = bsObj.find_all(&rsquo;li&rsquo;, class_=&ldquo;item-info01&rdquo;) artnum = 0 for li in lis: artnum = artnum + 1 if artnum &lt;=3: #控制显示前三篇 name = li.find(&lsquo;h3&rsquo;).text.strip() namepath = dirname +&rsquo;/&rsquo; + name if not os.path.exists(namepath): #如果文件夹不存在，则创建 os.mkdir(namepath) artlink = li.find(&lsquo;a&rsquo;)[&lsquo;href&rsquo;] url2 = urljoin(url,artlink) html2 = requests.get(url2,headers=header) bsObj2 = BeautifulSoup(html2.content, &rsquo;lxml&rsquo;) lis2 = bsObj2.find_all(&lsquo;div&rsquo;,class_=&ldquo;article&rdquo;) for para in lis2: ## 爬取文章内容 try: paras = para.find_all(&lsquo;span&rsquo;) with open(namepath + &lsquo;/&rsquo; + name + &lsquo;.txt&rsquo;, &lsquo;w&rsquo;) as f: f.write(name+&rsquo;\n&rsquo;) for parasub in paras: f.write(parasub.text.strip()+&rsquo;\n&rsquo;) except: print(&ldquo;没有发现文章!&rdquo;) ## 爬取文章图片 lis3 = bsObj2.find_all(&lsquo;p&rsquo;) k = 1 for picls in lis3: try: imglink = picls.find(&lsquo;img&rsquo;)[&lsquo;src&rsquo;] url3 = urljoin(url, imglink) html3 = requests.get(url3, headers=header) with open(namepath+&rsquo;/&rsquo;+name + str(k) +imglink[imglink.rfind(&rsquo;.&rsquo;):], &lsquo;wb&rsquo;) as f: f.write(html3.content) k = k+1 except : pass {% endcode %}
{% code Python展示图片 lang:python %}
